INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.a1-math371', 'stk-mr.a1', 'MATH 371', 'doc', '{"docs": [{"id": "stk-dr-m68372", "n": "Dr. Hattan Tawfiq", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 182 MATH 371\n\nالتحضير :\nبداية المحاضرة على الكمبيوتر ، ينادي بالاسماء. بعد فترة (تقريبا حول ميجر ٢) ما قام يحضّر إلا إذا شاف العدد قليل بقوة.\n\nطريقة الشرح :\nعلى السبورة بشكل اساسي ، يستخدمها للاشتقاقات والتوضيحات وشرح الطريقة اللي نتعلمها ، بعد كذا يفتح الشرايح ويمر على باقي الاشياء اللي ما وضحها أو ما تنفع على السبورة (مثل الـ Algorithm على سبيل المثال).\nفي المجمل الشرح كويس ، الشيء السلبي أن حل الأمثلة عنده قليل جدا ، ممكن هو شايف أن المنهج لطلاب مستوى ثالث ما فيه داعي توقف على راسهم وتحل امثلة كثير.\n\nالكويزات :\nلا توجد ، الكلاس وورك كان كله على الهومورك. الهوموركات كانت كثيرة بعض الشيء لكنها قصيرة ، يعني كل واحد يجيك سؤال او اثنين عشان تتدرب على فكرة معينة شرحها.\n\nالمياجر:\nمشتركة مع باقي الدكاترة ، مستوى الاول كان وسط مائل للصعوبة بسبب حادثة صارت بداية الترم مع منسق المادة -اللي اخذوا المادة هالترم يعرفون وش اتكلم عنه 😆- بينما الثاني كان سهل.\n\nالفاينلات :\nمشترك ، مثل ميجر ٢ سهل.\n\nالقريد النهائي:\nA+\n\nالصوت:\nواضح ومسموع من آخر الكلاس ، الشرح مخلوط عربي على انجليزي.\n\nإضافات :\n١. تقريبا كل يوم خميس بياخذكم لمعمل في مبنى ٥ ، تبدون تتعلمون فيه على الماتلاب وتسوون Assignments متعلقة باللي تدرسونه.\n٢. ركز على الاسئلة اللي يطلب منك انك تحلها للتدريب ، تراها مهمة جدا.\n٣. تصحيح الدكتور حقاني وبتاخذ اللي تستاهله ، ولاحظت انه يتساهل في كثير من الاحيان.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1508918-math371", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hattan-tawfiq/68372/29", "user": "Mr.A1", "ts": 1556095829000, "tid": 68372, "pn": 29}}]}', 1556095829000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-super_mario-math371', 'stk-super_mario', 'MATH 371', 'doc', '{"docs": [{"id": "stk-dr-m68381", "n": "Dr. Jaafar Al-Mutawa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 191\nMath 371\nالتحضير : مرن جدا بالتحضير واحيان كثير مايحضر\nطريقة الشرح : يشرح الفكرة وبعدها يحل عالسبورة ويستخدم الماتلاب اذا في اكواد والدتور شرحه ممتاز جدا تستمتع اذا ركزت معه الوقت يمشي بسرعه وكان حريص ان الطالب يفهم.\nالكويزات : متوسطة الصعوبه شبيهه باكزامبلز الكتاب.\nالمياجر: common\nالفاينلات : common\nالقريد النهائي: ِA+\nالصوت: واضح\nإضافات :\nالدكتورممتاز جدا ويفرض عليك احترامه, يهمه كثير ان الطالب يفهم ويشد حيله لكن احقاقا للحق الدكتور عملي بالتعامل مستحيل يزودك بالمياجر بدون سبب, ولكن بشكل عام الدكتور محترم الى ابعد حد وبيفرض عليك احترامه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1523763-math371", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jaafar-al-mutawa/68381/62", "user": "Super_Mario", "ts": 1594161633000, "tid": 68381, "pn": 62}}]}', 1594161633000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kirsty13-math371', 'stk-kirsty13', 'MATH 371', 'doc', '{"docs": [{"id": "stk-dr-m68581", "n": "Dr. M Yousuf", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH371-203 (اونلاين كلاس ومد وفاينل حضوري)\nالتحضير: ينزل اللستة من التيمز\nالشرح: حاولت اركز معه بالبداية لكن ماقدرت , الرجال ما عنده نوت جاهزة ! جالس يفتح الكتاب قدامنا ويسوي النوت لايف معنا والشي هذا يخليه يسلك بالشرح لدرجة انه بالغالب يحل المثال المحلول بالخطوات بالكتاب ! . الاكسنت اوضح بكثير من باقي الدكاترة الباكستانيين اللي درست عندهم للامانة .\nالكويزات: عطانا 6 كويزات ا5 منها فاينل انسر وواحد اختيارات وقال باخذ افضل 5 وجحدنا بالاخير بحجة الافرج واصلا الكورس مافيه الا سكشن واحد بس ! , الكويزات مستواها سهل جدا ويكفيك انك تحل الاسئلة المقترحة بالسيلابس عشان تضمن الفل مارك , مدة الكويز اخر نص ساعة من المحاضرة ويمديك تخلص الكويز ب ربع ساعة من سهولته .\nالمد: كان يجيب اسئلة من الاولد اكزامز نسخ لصق وجميع الافكار يا انها من الاسئلة المقترحة او الاولد اكزامز , المد كان حضوري ورتن وتصحيح الدكتور يركز على الفاينل انسر اذا كان غلط سلم على درجة السؤال لكن انا كنت اكتب الخطوات بالتفصيل الممل فكان يعطيني بارشل كويس عكس اغلب الشباب , نظام الدكتور بالتصحيح سيء لكن اذا كتبت الخطوات بالتفصيل لعله يتساعد معك , اضافة اخرى الوقت كان جدا حرج يعني عطانا 5 دقايق زيادة وحرفيا بدونها كنت بترك سؤال ناقص وانا اعرف احله.\nالفاينل: نفس سالفة المد , لكنه هالمرة تجمل بالتصحيح عكس المرة الاولى ومن قوة ماهو ينسخ ويلصق جاب لنا سؤال مكرر من المد . بالنسبة للوقت متيريال الفاينل يحتاج وقت اكثر بالحل من المد وهالمرة ما عطانا 5 دقايق اضافية فاغلب الشعب تنكب , الدكتور عنده مشكلة باختيار المدة الزمنية للاختبارات .\nاضافات : الدكتور بشكل عام ممتاز لكن اللي خلا الطلاب يكرهونه هي اخلاقه وطريقة تعامله مع الطلاب , ايضا تصحيحه للبروجكت يدور اي شي عشان ينقصك عليه ! يعطي 14/15 كثير لكن الفل مارك واحد او اثنين ويناقض نفسه اذا جيت تسأله عن السبب ولا يعترف بالغلط يكابر واسلوبه مستفز جدا , ايضا الفورملا شيت اللي يحطها الدكتور للمد والفاينل جدا جدا سيئة شبه ما منها فايدة ويوم كلمناه انها ما تشفع للاختبار وكذا قال بالحرف الواحد “Then drop the course” , بالنسبة لتوزيع القريدات عنده فما عطانا غير انه ال +A من 268.5 , سمعت من اكثر من شخص جابوا 268 ونزلها لهم بالبورتال +A وفي الترانسكبت A ! الدكتور جدا جحود وصار لي موقف معه في احد الكويزات لذلك لا تضمن كلامه .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531287-math371", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-yousuf/68581/43", "user": "Kirsty13", "ts": 1629115665000, "tid": 68581, "pn": 43}}]}', 1629115665000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
